"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisLogoCloudContent } from "./components/logo-cloud/content";
import View1 from "./components/logo-cloud/variants/02-grid";
const variants = {"grid":View1};
export type { ArtemisLogoCloudContent, ArtemisLogoCloudLogo } from "./components/logo-cloud/content";
export interface ArtemisLogoCloudProps { className?: string; variant?: "grid"; /** The words on the logo cloud; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisLogoCloudContent>; }
export function ArtemisLogoCloud({ className, variant = "grid", content }: ArtemisLogoCloudProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** One logo in the cloud. */
export interface ArtemisLogoCloudLogo {
  /**
   * The company's name, shown beside the icon. All layouts; carousel also lists every name for screen readers.
   * Keep names unique, since grid, columns and carousel tell logos apart by name.
   */
  name: string;
  /** A logo image shown in place of the icon and name, sized to the row; its alt text names the logo. All layouts. */
  image?: { src: string; alt: string };
  /** The icon beside the name. All layouts, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis logo cloud. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisLogoCloudContent {
  /** A small label over the headline. columns and carousel. */
  badge?: string;
  /** The heading. All layouts; marquee shows it as a small line over the logos. */
  headline: string;
  /** A line under or beside the headline. grid, columns and carousel. */
  subhead?: string;
  /**
   * The logos. All layouts: marquee scrolls them in one row, grid rolls them through eight cells, columns deals them
   * into four scrolling lanes and carousel turns them through two or four slots. Twelve look best; grid needs more
   * than eight to roll.
   */
  logos: ArtemisLogoCloudLogo[];
}

"use client";
// @zeus-internal
import { AnimatePresence, motion } from "motion/react";
import { type ComponentType, useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisLogoCloudContent, ArtemisLogoCloudLogo } from "../content";
import { CELL_COUNT, defaultLogos, ICONS, ROLL_INTERVAL_MS } from "./02-grid/logos";
const DEFAULT = {
    headline: "The fastest teams build with Artemis",
    subhead: "From seed-stage startups to platform teams shipping at scale.",
    logos: defaultLogos,
} satisfies ArtemisLogoCloudContent;
const CELL_CLASS = "art:group art:-mt-px art:-ml-px art:relative art:flex art:h-[5.5rem] art:items-center art:justify-center art:overflow-hidden art:border-border/60 art:border-t art:border-l art:transition-colors art:hover:bg-muted/40";
const LOGO_CLASS = "art:flex art:items-center art:gap-2.5 art:text-muted-foreground/75 art:transition-colors art:group-hover:text-foreground";
const ROLL_TRANSITION = { duration: 0.7, ease: ARTEMIS_EASE_OUT };
function LogoCell({ index, logo, slot }: {
    index: number;
    logo: ArtemisLogoCloudLogo;
    slot: number;
}) {
    const Icon: ComponentType<{ className?: string; strokeWidth?: number }> = logo.icon ?? ICONS[slot % ICONS.length];
    return (<motion.div className={CELL_CLASS} initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, margin: "-40px" }} transition={{ duration: 0.4, ease: ARTEMIS_EASE_OUT, delay: Math.min(index, 6) * 0.05 }}>
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span key={logo.name} className={LOGO_CLASS} initial={{ opacity: 0, y: 16, filter: "blur(7px)" }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} exit={{ opacity: 0, y: -16, filter: "blur(7px)" }} transition={ROLL_TRANSITION}>
          {logo.image ? <img src={logo.image.src} alt={logo.image.alt} className="art:h-7 art:w-auto art:max-w-full art:object-contain"/> : <>
          <Icon className="art:size-5" strokeWidth={1.75} aria-hidden="true"/>
          <span className="art:font-semibold art:text-lg art:tracking-tight">{logo.name}</span>
          </>}
        </motion.span>
      </AnimatePresence>
    </motion.div>);
}
export default function LogoCloudGrid({ content }: { content?: Partial<ArtemisLogoCloudContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const [tick, setTick] = useState(0);
    const paused = useRef(false);
    useEffect(() => {
        const id = window.setInterval(() => {
            if (paused.current)
                return;
            setTick((t) => t + 1);
        }, ROLL_INTERVAL_MS);
        return () => window.clearInterval(id);
    }, []);
    const offset = (tick * CELL_COUNT) % copy.logos.length;
    return (<div className="art:w-full">
      <section className="art:w-full art:px-4 art:py-16 art:@min-[640px]/artemis:px-8">
        <div className="art:mx-auto art:w-full art:max-w-5xl">
          <div className="art:mx-auto art:max-w-xl art:text-center">
            <h2 className="art:text-balance art:font-sans art:text-foreground art:leading-tight art:text-4xl art:font-medium">
              {copy.headline}
            </h2>
            <p className="art:mt-3 art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
              {copy.subhead}
            </p>
          </div>
          <div className="art:mt-10 art:grid art:grid-cols-2 art:overflow-hidden art:rounded-2xl art:border art:border-border/60 art:@min-[640px]/artemis:grid-cols-4" onMouseEnter={() => {
            paused.current = true;
        }} onMouseLeave={() => {
            paused.current = false;
        }}>
            {Array.from({ length: CELL_COUNT }, (_, i) => {
            const slot = (i + offset) % copy.logos.length;
            return (<LogoCell key={i} index={i} logo={copy.logos[slot]} slot={slot}/>);
        })}
          </div>
        </div>
      </section>
    </div>);
}

