]);
/** The logos the grid shows when it is given none. */
export const defaultLogos: ArtemisLogoCloudLogo[] = [
    { name: "Workspace" },
    { name: "Group A" },
    { name: "Group B" },
    { name: "Group C" },
    { name: "Group D" },
    { name: "Group E" },
    { name: "Group F" },
    { name: "Group G" },
    { name: "Group H" },
    { name: "Group I" },
    { name: "Group J" },
    { name: "Group K" },
];
